DO $$ BEGIN
IF NOT EXISTS(SELECT 1 FROM schema_migrations WHERE version=7) THEN
 ALTER TABLE workspaces ADD COLUMN execution_paused boolean NOT NULL DEFAULT false;
 ALTER TABLE agents ADD COLUMN execution_paused boolean NOT NULL DEFAULT false;
 ALTER TABLE runs ADD COLUMN paused_by_workspace boolean NOT NULL DEFAULT false;
 ALTER TABLE plans ADD COLUMN max_environments integer NOT NULL DEFAULT 0 CHECK(max_environments BETWEEN 0 AND 100);
 ALTER TABLE plans ADD COLUMN max_running_environments integer NOT NULL DEFAULT 0 CHECK(max_running_environments BETWEEN 0 AND 100);
 ALTER TABLE plans ADD COLUMN runtime_minutes integer NOT NULL DEFAULT 0 CHECK(runtime_minutes BETWEEN 0 AND 1000000);
 ALTER TABLE plans ADD COLUMN environment_templates jsonb NOT NULL DEFAULT '[]';
 UPDATE plans SET max_environments=CASE id WHEN 'starter' THEN 1 WHEN 'pro' THEN 3 ELSE 0 END,max_running_environments=CASE id WHEN 'starter' THEN 1 WHEN 'pro' THEN 2 ELSE 0 END,runtime_minutes=CASE id WHEN 'starter' THEN 300 WHEN 'pro' THEN 1200 ELSE 0 END,environment_templates=CASE WHEN id IN('starter','pro') THEN '["browser","development"]'::jsonb ELSE '[]'::jsonb END;
 ALTER TABLE accounts ADD COLUMN runtime_included integer NOT NULL DEFAULT 0 CHECK(runtime_included>=0);
 ALTER TABLE accounts ADD COLUMN runtime_purchased integer NOT NULL DEFAULT 0 CHECK(runtime_purchased>=0);
 ALTER TABLE accounts ADD COLUMN runtime_disputed boolean NOT NULL DEFAULT false;
 ALTER TABLE accounts ADD COLUMN runtime_debt integer NOT NULL DEFAULT 0 CHECK(runtime_debt>=0);
 ALTER TABLE accounts ADD COLUMN runtime_period text;
 ALTER TABLE accounts ADD COLUMN runtime_period_end timestamptz;
 ALTER TABLE accounts ADD COLUMN runtime_plan text;
 ALTER TABLE accounts ADD COLUMN runtime_allowance integer NOT NULL DEFAULT 0;
 ALTER TABLE infrastructure_hosts ADD COLUMN self_service boolean NOT NULL DEFAULT false;
 ALTER TABLE infrastructure_hosts ADD COLUMN max_running integer NOT NULL DEFAULT 10 CHECK(max_running BETWEEN 1 AND 500);
 ALTER TABLE infrastructure_hosts ADD COLUMN cpu_limit integer NOT NULL DEFAULT 8 CHECK(cpu_limit BETWEEN 1 AND 1024);
 ALTER TABLE infrastructure_hosts ADD COLUMN memory_limit_mb integer NOT NULL DEFAULT 8192 CHECK(memory_limit_mb BETWEEN 256 AND 1048576);
 ALTER TABLE environment_templates ADD COLUMN runtime_rate integer NOT NULL DEFAULT 1 CHECK(runtime_rate BETWEEN 1 AND 100);
 ALTER TABLE customer_environments ADD COLUMN self_service boolean NOT NULL DEFAULT false;
 ALTER TABLE customer_environments ADD COLUMN billing_active boolean NOT NULL DEFAULT false;
 ALTER TABLE customer_environments ADD COLUMN access_blocked boolean NOT NULL DEFAULT false;
 ALTER TABLE customer_environments ADD COLUMN paid_until timestamptz;
 ALTER TABLE customer_environments ADD COLUMN reservation text;
 ALTER TABLE customer_environments ADD COLUMN relay_seen timestamptz;
 ALTER TABLE customer_environments ADD COLUMN shutdown_requested boolean NOT NULL DEFAULT false;
 ALTER TABLE customer_environments ADD COLUMN runtime_rate integer NOT NULL DEFAULT 1;
 ALTER TABLE customer_environments ADD COLUMN reservation_period text;
 ALTER TABLE customer_environments ADD COLUMN started_at timestamptz;
 ALTER TABLE environment_credentials ADD COLUMN relay_secret text;
 ALTER TABLE environment_credentials ADD COLUMN relay_hash text;
 CREATE TABLE runtime_ledger(id text PRIMARY KEY,account_id text NOT NULL REFERENCES accounts ON DELETE CASCADE,environment_id text REFERENCES customer_environments ON DELETE SET NULL,kind text NOT NULL,amount integer NOT NULL,included_part integer NOT NULL DEFAULT 0,purchased_part integer NOT NULL DEFAULT 0,period text,reason text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
 CREATE TABLE runtime_products(id text PRIMARY KEY,name text NOT NULL,minutes integer NOT NULL CHECK(minutes BETWEEN 1 AND 1000000),price_cents integer NOT NULL CHECK(price_cents BETWEEN 1 AND 10000000),stripe_price_id text,active boolean NOT NULL DEFAULT false);
 INSERT INTO runtime_products VALUES('runtime-300','300 Laufzeit-Minuten',300,500,NULL,false);
 CREATE TABLE runtime_orders(id text PRIMARY KEY,account_id text NOT NULL REFERENCES accounts ON DELETE CASCADE,product_id text NOT NULL,minutes integer NOT NULL,price_cents integer NOT NULL,stripe_price_id text NOT NULL,stripe_session_id text UNIQUE,payment_intent text,paid_total_cents integer,disputed boolean NOT NULL DEFAULT false,status text NOT NULL DEFAULT 'pending',refunded_cents integer NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now());
 CREATE TABLE environment_tickets(id text PRIMARY KEY,environment_id text NOT NULL REFERENCES customer_environments ON DELETE CASCADE,generation integer NOT NULL,parent_session text NOT NULL REFERENCES sessions ON DELETE CASCADE,expires_at timestamptz NOT NULL DEFAULT now()+interval '45 seconds');
 CREATE TABLE environment_sessions(id text PRIMARY KEY,environment_id text NOT NULL REFERENCES customer_environments ON DELETE CASCADE,generation integer NOT NULL,parent_session text NOT NULL REFERENCES sessions ON DELETE CASCADE,expires_at timestamptz NOT NULL DEFAULT now()+interval '8 hours');
 CREATE INDEX environment_sessions_expiry ON environment_sessions(expires_at);
 INSERT INTO schema_migrations(version) VALUES(7);
END IF;
END $$;
